C = dict(id='GL-15', title='Tele and Video Conferencing Operations', group='Digital and Technology', level=3,
 summary='Run reliable, accessible online meetings and events: set up rooms, test audio and video, manage people and recording, and fix problems live.',
 outcomes=['Explain what makes a call clear: audio, light, network and etiquette.', 'Set up a room, a camera and a microphone for a clean picture and sound.', 'Analyse call quality using simple tests and logs.', 'Create run sheets, joining guides and accessibility settings for a live session.', 'Evaluate sessions with attendee feedback and technical measures.'],
 task='Host and technically run three online sessions (small meeting, workshop, larger webinar) with run sheets, recordings where agreed, and feedback.',
 cond='A computer or phone, a free conferencing tool, a headset or microphone, a second person to act as guest, a mentor and a peer circle. About 8 weeks part-time.',
 std='Test completed 30 minutes before each session; audio understood by every attendee; captions or notes offered; recording only with consent; attendee satisfaction 4 of 5 or better; any fault fixed or worked around within 3 minutes.',
 who='Office staff, teachers, event assistants, support staff, community hosts.', req='Basic computer skills.',
 safety='Record only with clear consent. Protect meeting links and passcodes. Never share a screen with private tabs open.',
 mods=[
 ('What makes a good call', 'Sound matters more than picture.', ['Audio first: a headset beats a laptop microphone.', 'Light from the front; camera at eye level.', 'Steady network: wire if you can; close heavy apps.', 'Quiet, tidy background and good manners.'], 'Window behind the speaker makes a silhouette; turning the desk so light falls on the face fixes it in one minute.', 'Set up your space and record a 1-minute test.', 'Test is clear in sound and face.'),
 ('Tools and rooms', 'Know the features before the day.', ['Waiting room, mute-all, chat, hand raise, breakout rooms.', 'Roles: host, co-host, presenter, attendee.', 'Passcodes and locked rooms for private meetings.', 'Open the tool on a phone as a guest to see what attendees see.'], 'A webinar with 80 attendees uses a co-host for questions so the host can present.', 'List the features you will use and test each.', 'All features tested with a guest.'),
 ('Audio and video setup', 'Test, adjust, test again.', ['Choose microphone and speaker; check levels.', 'Use headphones to stop echo.', 'Check camera framing: head and shoulders.', 'Test screen sharing and audio sharing.'], 'Echo appears when two laptops in one room are open: mute one, use headphones.', 'Run a 15-minute test with a partner and fix three issues.', 'Three issues logged with fixes.'),
 ('Network and quality', 'Know the numbers behind a bad call.', ['Speed: a video call needs roughly 2 to 4 Mbit/s each way.', 'Delay above 150 ms feels awkward.', 'Lost data packets (small chunks of data) cause choppy sound.', 'Fallback: turn off video, then call in by phone.'], 'Link gives 1.5 Mbit/s up: turn off camera for non-speakers; speaker keeps video.', 'Run a speed and delay test three times and record.', 'Three readings in a table.'),
 ('Access and inclusion', 'Everyone should be able to take part.', ['Captions on; share slides before the call.', 'Describe visuals aloud.', 'Allow chat as well as voice.', 'Time zones: offer two times or a recording.'], 'A deaf attendee needs captions; check them before the session and offer notes afterwards.', 'Build an access checklist and use it.', 'Checklist applied to one session.'),
 ('Run the session', 'A run sheet keeps the host calm.', ['Run sheet: time, task, who, backup.', 'Open the room 10 minutes early; greet people as they arrive.', 'Set ground rules; manage questions.', 'Record only after announcing it and getting consent.'], 'Minute 0 welcome, 2 rules, 5 content, 40 questions, 50 summary, 55 close.', 'Write a run sheet and host a 30-minute session.', 'Run sheet followed; times kept within 5 minutes.'),
 ('Fix problems live', 'Problems will happen; calm fixes keep trust.', ['Common: no sound, frozen picture, wrong room, someone cannot join.', 'Say what you are doing; give a plan B.', 'Send the joining link again and a phone number.', 'Log the fault and cure.'], 'Presenter freezes; co-host reads the notes while the presenter rejoins; lost time 90 seconds.', 'Practise five fault drills and time each.', 'Each drill fixed in 3 minutes or less.'),
 ('Measure and improve', 'Learn from every session.', ['Ask attendees for a score and one comment.', 'Check join success rate and drop-offs.', 'Update the joining guide.', 'Plan 90 days.'], '38 of 40 joined without help = 95%; satisfaction 4.4.', 'Report on three sessions.', 'Report compares sessions and lists three changes.')],
 quiz=[('Why audio first?', 'People tolerate poor picture but not poor sound.'), ('Where should light come from?', 'In front of you.'), ('What stops echo?', 'Headphones and one open microphone per room.'), ('Bandwidth needed per video participant?', 'Roughly 2 to 4 Mbit/s each way.'), ('Why use captions?', 'They help people who cannot hear well and anyone in a noisy place.'), ('When may you record?', 'After announcing and with consent.'), ('What is in a run sheet?', 'Time, task, who and backup.'), ('Plan B when video fails?', 'Turn off cameras or join by phone.'), ('Why open as a guest?', 'To see what attendees see.'), ('How do you compute join success?', 'Joined without help divided by invited, times 100.')],
 rubric=[('Set-up', 'Clear sound and picture', 'Network and fallback tested'), ('Run sheet', 'Followed within 5 minutes', 'Backup used smoothly'), ('Access', 'Checklist applied', 'Feedback from a user needing support'), ('Fault handling', 'Drills under 3 minutes', 'Faults prevented by testing'), ('Evaluation', 'Report for three sessions', 'Changes made and re-measured')],
 jobs=[('Webinar producer', 'Runs large online events'), ('Meeting room technician', 'Sets up rooms and tools'), ('Virtual classroom assistant', 'Supports teachers online'), ('Event support assistant', 'Handles chat and questions')],
 next='Virtual Event Planning; IT Service and Support; Online Tutoring Platform.',
 local='Recording and cross-border calls may need consent and notices; check your place and your attendees\' places.',
 evidence='Your evidence: space test, tool test list, run sheets, fault drill log, access checklist, three-session report.',
 ladder=[('Basics of calling', 'Join an online meeting with camera, sound and your name set up properly. Notes: test your set-up with a friend before the call. Standard: you are heard and seen clearly in the first minute.'), ('Awareness', 'Explain the main parts of a conference session (audio, video, sharing, chat) and the usual faults. Notes: make a one-page fault card for a participant. Standard: five faults, each with a fix.'), ('Foundation', 'Host a small meeting with a run sheet, muted guests, shared screen and a chat monitor. Notes: use a free tool with three friends. Standard: starts on time, agenda kept and notes sent.'), ('Practitioner', 'Run a workshop with breakout rooms, polls and a recording where everyone agrees. Notes: consent is taken at the start and in writing. Standard: recording only with consent, and feedback from at least five attendees.'), ('Specialist', 'Host and technically run three online sessions (small meeting, workshop, larger webinar) with run sheets, recordings where agreed, and feedback. Notes: each run sheet has a back-up plan for audio failure. Standard: all three sessions run to time, with a fault log and a ratings summary.'), ('Advanced', 'Run large events with a producer, moderators and an accessibility plan. Notes: add captions, a support line and a rehearsal checklist. Standard: rehearsal completed, accessibility checked, drop-out rate reported.'), ('Super expert', 'Set the meeting-quality standard (audio, camera, access, recording consent) and teach the hosts who use it. Notes: review call-quality logs and complaints every quarter.')])

C['deep'] = dict(mods=[
 ('Relying on a laptop microphone.', 'A USB headset removes echo and clatter in one change.', 'What audio gear do you use?'),
 ('Opening the tool for the first time as host on the day.', 'A guest login shows attendees cannot see the poll; fix before the event.', 'What did your guest test find?'),
 ('Testing alone.', 'Testing with a partner shows echo when both speakers are open.', 'What did your partner hear?'),
 ('Ignoring upload speed.', 'Download is fast but upload is 1 Mbit/s; the speaker\'s video freezes.', 'What are your three readings?'),
 ('Adding captions at the end.', 'Captions on from the start help a noisy-room attendee as well.', 'Which access items did you set?'),
 ('No run sheet, so time slips.', 'A 5-minute chat on the welcome slide cuts the questions by half.', 'What did you cut?'),
 ('Panicking in a fault.', 'The producer says "we will be back in two minutes" and posts the backup link.', 'What is your plan B?'),
 ('Not asking for feedback.', 'A one-question poll gives a 4.4 score and one useful comment.', 'What did attendees say?')],
 gloss=[('Host', 'The person who controls the meeting.'), ('Co-host', 'A helper with host controls.'), ('Breakout room', 'A small group space.'), ('Latency', 'Delay between speaking and hearing.'), ('Bandwidth', 'Data speed.'), ('Run sheet', 'A timed plan.')],
 cases=[('The echo', 'Everyone hears themselves.', 'Cause and fix?', 'Two open microphones in a room; mute one, use headphones.'),
        ('The late guest speaker', 'The speaker has not joined at start time.', 'What do you do?', 'Start with the welcome, call the number you hold, move the slot if possible, and keep the time.')])
C['deep']['extra'] = [
 ['Test with the same device attendees will use if you can.', 'Sit about an arm\'s length from the camera for steady framing.'],
 ['Learn the keyboard shortcuts for mute and chat.', 'Turn off notifications before sharing a screen.'],
 ['Record a test and listen back with headphones.', 'Note background noise sources and remove them.'],
 ['Close heavy programs and cloud sync during calls.', 'Use a wired link for important events.'],
 ['Describe images aloud and name speakers before they talk.', 'Share a short joining guide in plain words.'],
 ['Share the run sheet with co-hosts only.', 'Assign someone to watch the chat for questions.'],
 ['Keep a phone dial-in as a backup.', 'Practise rejoining as the host from another device.'],
 ['Compare numbers between sessions to see what improved.', 'Share recordings only with those who agreed.']]

_ex = ['Window behind the speaker makes a silhouette. Turning the desk so light falls on the face fixes it in one minute, and a lamp behind the screen adds balance.', 'A webinar with 80 attendees uses a co-host for questions so the host can present; 12 questions are answered live and 9 in writing afterwards.', 'Echo appears when two laptops in one room are open. Muting one and using headphones ends it, and the test log records the cause.', 'Upload speed is 1.5 Mbit/s. Non-speakers turn off video; the speaker keeps video on; the session runs without freezing.', 'A deaf attendee needs captions. You check them before the session, send slides the day before and offer notes afterwards.', 'Run sheet: minute 0 welcome, 2 rules, 5 content, 40 questions, 50 summary, 55 close. The welcome overruns by 3 minutes, so questions are shortened.', 'The presenter freezes. The co-host reads the notes while the presenter rejoins; the lost time is 90 seconds and the fault log records it.', '38 of 40 invitees joined without help (95%), satisfaction was 4.4, and the joining guide gets a clearer link.']
_extra = ['Test the microphone level by speaking at normal volume and watching the meter.', 'Place the camera at eye level using books if needed.', 'Remove clutter from the background or use a plain wall.', 'Close your email and chat notifications before sharing.', 'Keep water and a spare charger within reach.', 'Open the joining link on a phone to see the guest view.', "Name your screen with your role, for example 'Host, your first name'.", "Save the participants' names for the thank-you note.", 'Practise muting and unmuting others politely.', 'Know where the chat save and attendance report are.', 'Keep the backup phone number in the invitation.', 'Offer a plain text summary of the session.', 'Check accessibility settings such as caption language.', 'Time each part against the run sheet.', 'Keep a note of any fault and its fix.', 'Write the lessons after each session in three lines.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Before any call, write a one-line purpose and a decision you need, such as choosing between two dates, and cap the agenda at three items so a 30-minute call ends with named owners.', 'Send the agenda at least 24 hours ahead with the join link and the time in two time zones. Then a team of ten does not lose five minutes to confusion at the start.'], ['Compare two platforms on a checklist of five points: maximum people, recording, captions, breakout rooms and phone dial-in, then pick the one that meets all five for your usual group size.', 'Keep a backup route ready, such as a second link or a phone number, and share it in the invite so a failed room costs two minutes rather than the whole session.'], ['Place a light in front of your face, not behind you. Set the camera at eye level by stacking books under a laptop until the top third of the screen meets your eyes.', 'Do a two-minute test recording each time: speak a sentence, play it back, and check that your voice is clear, not echoing, and that the lowest background hum is gone.'], ['Test your speed at the time of day you will meet, and aim for at least 3 Mbit/s up and down for one video call; if it falls below that, ask guests to turn cameras off.', 'If the picture freezes, switch off your own video first, then close other tabs and downloads, and only then move closer to the router or plug in a network cable.'], ['Turn on live captions, share slides as a file ahead of time, and describe any image you show in one spoken sentence so people using screen readers or slow links are not left out.', 'Keep to a pace of one idea every two minutes, pause for five seconds after each question, and offer chat as well as voice so quieter or non-native speakers can join.'], ['Open the room ten minutes early, greet people by name as they join, and give a rule in the first minute: mute when not talking, use the hand-raise button to speak.', 'Assign a co-host to watch the chat and the clock; when the planned time for an item is up, they signal you so a 60-minute session actually finishes in 60.'], ['Keep a one-page fix list: no sound means check the output device and mute switch; no video means check browser permissions; lag means turn off video. Tape it beside your screen.', 'If the main presenter drops out, the co-host should take over within 30 seconds by saying what happens next, such as a short break or sharing the next slide.'], ['After each session, send a three-question survey: was the audio clear, was the time well used, what one thing would you change. Aim for a response rate above 40 percent.', 'Keep a simple log with date, number joined, number who stayed to the end, and problems; after five sessions, compare the figures to see which fix helped most.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {1: "A sales call looks dull because the speaker sits far from the camera. Moving the camera to eye level and one arm's length closer makes the face fill the frame, and attendees comment on the clarity.", 2: 'A 15-person team workshop uses breakout rooms of 3 people. The host sets 10 minutes, a shared notes page per room, and all five groups report back on time.', 3: "A speaker's voice crackles on a phone microphone. Switching to a wired headset and moving away from the laptop fan clears the sound, and the check list records the headset as standard.", 5: 'A learner with slow internet cannot watch video. You offer a phone dial-in, send the slides as a small file, and she follows the whole session at no extra cost.', 6: 'A 45-minute training run sheet: minute 0 check sound, 5 icebreaker poll, 10 demo, 30 practice, 40 questions, 45 close. A poll runs long, so the practice is cut to 8 minutes.', 7: "A guest's microphone is muted and she does not know. The host sends a private message with the unmute steps and she is heard within 40 seconds, so the session continues.", 8: 'After a session 27 of 30 guests answered the survey: 22 of those answers rated clarity 4 or 5 (81%). The top comment asks for slides in advance, so the next invitation attaches them.'}
C['deep']['mods'] = [(m[0], _dupfix.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ["You will plan a call around one purpose, a decision and a short agenda sent in advance, so a half-hour meeting ends with named owners.", "You will compare platforms against a five-point checklist and prepare a backup route, so a failed room costs minutes rather than the session.", "You will set up lighting, camera height and a recorded sound test, so participants hear you clearly and see you without distraction.", "You will test connection speed at the real meeting time and apply an ordered fix sequence, so freezing pictures are handled calmly.", "You will use captions, advance files, spoken image descriptions and chat options, so people with different needs and connections can all contribute.", "You will open early, set ground rules in the first minute and use a co-host for chat and time, so sessions finish as planned.", "You will keep a one-page fix list and a handover plan for a dropped presenter, so problems are resolved without losing the audience.", "You will gather a short survey and a session log, then compare figures across sessions to learn which change actually improved quality."]
